// src/components/layout/header.tsx
'use client'; // <-- 1. Tambahkan ini di baris paling atas

import { useState } from 'react'; // <-- 2. Impor useState
import { Search, Bell } from 'lucide-react';
import Image from 'next/image';

const Header = () => {
  // 3. Buat state untuk menyimpan nilai dari input pencarian
  const [searchTerm, setSearchTerm] = useState('');

  // Untuk melihat keajaibannya, kita bisa log state-nya ke konsol
  console.log('Teks yang diketik:', searchTerm);

  return (
    <header className="flex justify-between items-center mb-8">
      <div>
        <h2 className="text-2xl font-bold text-brand-text-primary">Welcome to Nogops</h2>
        <p className="text-brand-text-secondary">Choose The Category</p>
      </div>
      <div className="flex items-center gap-6">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
          <input
            type="text"
            placeholder="Search something"
            className="bg-white pl-10 pr-4 py-2 rounded-lg w-64 focus:outline-none"
            value={searchTerm} // <-- 4a. Tampilkan nilai dari state
            onChange={(e) => setSearchTerm(e.target.value)} // <-- 4b. Update state setiap kali ada ketikan
          />
        </div>
        <Bell className="text-gray-600 cursor-pointer" />
        <div className="flex items-center gap-3">
          <Image
            src="https://i.pravatar.cc/40?u=sheillapoetri"
            alt="Admin"
            width={40}
            height={40}
            className="rounded-full"
          />
          <div>
            <p className="font-semibold text-sm">Sheilla Poetri</p>
            <p className="text-xs text-brand-text-secondary">Admin</p>
          </div>
        </div>
      </div>
    </header>
  );
};

export default Header;